// Calculate years of service from dateOfJoining (DD.MM.YYYY)
const dateOfJoiningStr = $('Work Anniversary Email Received').item.json.body.dateOfJoining || '';
const employeeName = $('Work Anniversary Email Received').item.json.body.name || '';
const employeeEmail = $('Work Anniversary Email Received').item.json.body.email || '';

if (!dateOfJoiningStr) {
  throw new Error('dateOfJoining is missing from the request');
}

// Parse DD.MM.YYYY
const parts = dateOfJoiningStr.split('.');
if (parts.length !== 3) {
  throw new Error(`Invalid dateOfJoining format: ${dateOfJoiningStr}. Expected DD.MM.YYYY`);
}

const day = parseInt(parts[0], 10);
const month = parseInt(parts[1], 10) - 1; // zero-indexed
const year = parseInt(parts[2], 10);

const joiningDate = new Date(year, month, day);
const today = new Date();

let yearsOfService = today.getFullYear() - joiningDate.getFullYear();
const monthDiff = today.getMonth() - joiningDate.getMonth();
if (monthDiff < 0 || (monthDiff === 0 && today.getDate() < joiningDate.getDate())) {
  yearsOfService--;
}

return [{ json: { employeeName, employeeEmail, dateOfJoining: dateOfJoiningStr, yearsOfService } }];

// LOG_ANNIVERSARY_EMAIL: Replace this node with actual email sending when email provider is configured
const employeeName = $('Calculate Tenure').item.json.employeeName;
